###############################################################################
(>&2 echo "Remediating rule 103/326: 'xccdf_org.ssgproject.content_rule_service_firewalld_disabled'")
# Remediation is applicable only in certain platforms
if rpm --quiet -q kernel-default && { rpm --quiet -q firewalld; }; then

SYSTEMCTL_EXEC='/usr/bin/systemctl'
if [[ $("$SYSTEMCTL_EXEC" is-system-running) != "offline" ]]; then
  "$SYSTEMCTL_EXEC" stop 'firewalld.service'
fi
"$SYSTEMCTL_EXEC" disable 'firewalld.service'
"$SYSTEMCTL_EXEC" mask 'firewalld.service'
# Disable socket activation if we have a unit file for it
if "$SYSTEMCTL_EXEC" -q list-unit-files firewalld.socket; then
    if [[ $("$SYSTEMCTL_EXEC" is-system-running) != "offline" ]]; then
      "$SYSTEMCTL_EXEC" stop 'firewalld.socket'
    fi
    "$SYSTEMCTL_EXEC" mask 'firewalld.socket'
fi
# The service may not be running because it has been started and failed,
# so let's reset the state so OVAL checks pass.
# Service should be 'inactive', not 'failed' after reboot though.
"$SYSTEMCTL_EXEC" reset-failed 'firewalld.service' || true

